import pathlib,tempfile,subprocess,os,json
root=pathlib.Path(__file__).parent
fodt='''<?xml version="1.0" encoding="UTF-8"?><office:document xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:style="urn:oasis:names:tc:opendocument:xmlns:style:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" xmlns:fo="urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0" office:version="1.3" office:mimetype="application/vnd.oasis.opendocument.text"><office:styles><style:style style:name="Standard" style:family="paragraph"><style:text-properties fo:font-family="Liberation Sans" fo:font-size="12pt"/></style:style></office:styles><office:automatic-styles><style:page-layout style:name="Page"><style:page-layout-properties fo:page-width="21cm" fo:page-height="29.7cm" fo:margin="2cm"/></style:page-layout><style:style style:name="Columns" style:family="section"><style:section-properties><style:columns fo:column-count="2" fo:column-gap="1cm"/></style:section-properties></style:style><style:style style:name="Right" style:family="paragraph"><style:paragraph-properties fo:break-before="column"/></style:style></office:automatic-styles><office:master-styles><style:master-page style:name="Standard" style:page-layout-name="Page"/></office:master-styles><office:body><office:text><text:h text:outline-level="1">Tagged reading order</text:h><text:section text:name="TwoColumns" text:style-name="Columns"><text:p>Left alpha Café</text:p><text:p>Left omega Ω</text:p><text:p text:style-name="Right">Right alpha</text:p><text:p>Right omega</text:p></text:section><text:p>Final paragraph.</text:p></office:text></office:body></office:document>'''
with tempfile.TemporaryDirectory(prefix='fc-tagged-') as temp:
 source=pathlib.Path(temp)/'baseline.fodt';source.write_text(fodt)
 for name,tagged in [('baseline',True),('untagged',False)]:
  target=pathlib.Path(temp)/(name+'.fodt');target.write_text(fodt)
  options=json.dumps({'UseTaggedPDF':{'type':'boolean','value':str(tagged).lower()}})
  subprocess.run([os.environ.get('FC_SOFFICE','soffice'),'--headless','--convert-to','pdf:writer_pdf_Export:'+options,'--outdir',str(root),str(target)],check=True)
(root/'expected.json').write_text(json.dumps({'logicalParagraphs':['Tagged reading order','Left alpha Café','Left omega Ω','Right alpha','Right omega','Final paragraph.']},ensure_ascii=False,indent=2)+'\n')
